content.content:
   1→/* ── SUPER DUPER Design System ──────────────────────────────────────
   2→ *  Native skin: ComfyUI dark theme palette
   3→ *  Accent: #4e9bcd (ComfyUI native blue)
   4→ *  Surfaces: neutral grey depth layers
   5→ *  Typography: Inter (sans) + JetBrains Mono (mono)
   6→ *  Slot colors: official ComfyUI dark theme
   7→ * ──────────────────────────────────────────────────────────────────── */
   8→
   9→/* Fonts loaded via sidebar.js <link> element (IBM Plex Sans + JetBrains Mono) */
  10→
  11→/* ── Design Tokens ──────────────────────────────────────────────── */
  12→
  13→:root {
  14→  /* ComfyUI Native Surfaces */
  15→  --sd-canvas: #1e1e1e;
  16→  --sd-panel: #2b2b2b;
  17→  --sd-card: #353535;
  18→  --sd-card-hover: #3a3a3a;
  19→  --sd-elevated: #404040;
  20→  --sd-input: #1a1a1a;
  21→
  22→  /* ComfyUI Native Text */
  23→  --sd-text-primary: #ddd;
  24→  --sd-text-secondary: #aaa;
  25→  --sd-text-muted: #888;
  26→  --sd-text-accent: #ccc;
  27→
  28→  /* ComfyUI Native Borders */
  29→  --sd-border: #4e4e4e;
  30→  --sd-border-subtle: #3a3a3a;
  31→
  32→  /* Accent (ComfyUI native blue -- replaces jade green) */
  33→  --sd-accent: #4e9bcd;
  34→  --sd-accent-dim: #4e9bcd33;
  35→  --sd-accent-subtle: #4e9bcd18;
  36→
  37→  /* Keep ALL slot colors unchanged */
  38→  --sd-slot-clip: #FFD500;
  39→  --sd-slot-clip-vision: #A8DADC;
  40→  --sd-slot-conditioning: #FFA931;
  41→  --sd-slot-controlnet: #6EE7B7;
  42→  --sd-slot-image: #64B5F6;
  43→  --sd-slot-latent: #FF9CF9;
  44→  --sd-slot-mask: #81C784;
  45→  --sd-slot-model: #B39DDB;
  46→  --sd-slot-style-model: #C2FFAE;
  47→  --sd-slot-vae: #FF6E6E;
  48→  --sd-slot-noise: #B0B0B0;
  49→  --sd-slot-guider: #66FFFF;
  50→  --sd-slot-sampler: #ECB4B4;
  51→  --sd-slot-sigmas: #CDFFCD;
  52→
  53→  /* Agent Identity Colors */
  54→  --agent-router: #00BB81;
  55→  --agent-intent: #FFD500;
  56→  --agent-execution: #64B5F6;
  57→  --agent-verify: #FF6E6E;
  58→  --agent-doctor: #B39DDB;
  59→
  60→  /* Typography */
  61→  --sd-font-sans: 'IBM Plex Sans', -apple-system, sans-serif;
  62→  --sd-font-mono: 'JetBrains Mono', monospace;
  63→
  64→  /* Spacing */
  65→  --sd-space-xs: 4px;
  66→  --sd-space-sm: 6px;
  67→  --sd-space-md: 8px;
  68→  --sd-space-lg: 12px;
  69→  --sd-space-xl: 16px;
  70→  --sd-space-2xl: 24px;
  71→  --sd-space-3xl: 32px;
  72→  --sd-msg-gap: 20px;
  73→  --sd-para-gap: 12px;
  74→
  75→  /* ADHD Spacing (generous, scannable) */
  76→  --space-xs: 6px;
  77→  --space-sm: 10px;
  78→  --space-md: 16px;
  79→  --space-lg: 24px;
  80→  --space-xl: 36px;
  81→
  82→  /* Motion */
  83→  --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
  84→  --duration-fast: 150ms;
  85→  --duration-med: 300ms;
  86→
  87→  --sd-transition: 150ms ease;
  88→}
  89→
  90→/* ── Layout Shell ───────────────────────────────────────────────── */
  91→
  92→.sd-header {
  93→  display: flex;
  94→  align-items: center;
  95→  justify-content: space-between;
  96→  padding: var(--sd-space-lg) var(--sd-space-xl);
  97→  font-family: var(--sd-font-sans);
  98→  font-size: 13px;
  99→  font-weight: 500;
 100→  letter-spacing: 0.02em;
 101→  color: var(--sd-text-primary);
 102→  border-bottom: 1px solid var(--sd-border-subtle);
 103→  background: var(--sd-panel);
 104→  flex-shrink: 0;
 105→}
 106→
 107→.sd-header__title {
 108→  flex: 1;
 109→}
 110→
 111→.sd-header__status {
 112→  font-family: var(--sd-font-mono);
 113→  font-size: 10px;
 114→  font-weight: 400;
 115→  color: var(--sd-text-muted);
 116→  text-transform: uppercase;
 117→  letter-spacing: 0.06em;
 118→}
 119→
 120→.sd-header__status--connecting {
 121→  color: #e6a23c;
 122→}
 123→
 124→.sd-header__status--disconnected {
 125→  color: #f56c6c;
 126→}
 127→
 128→/* ── Stage Indicator ────────────────────────────────────────────── */
 129→
 130→.sd-stage-bar {
 131→  display: flex;
 132→  align-items: center;
 133→  gap: var(--space-xs);
 134→  padding: var(--space-xs) var(--space-md);
 135→  background: var(--sd-accent-subtle);
 136→  border-bottom: 1px solid var(--sd-border-subtle);
 137→  flex-shrink: 0;
 138→  font-size: 12px;
 139→  animation: sd-pulse 1.5s ease-in-out infinite;
 140→}
 141→
 142→.sd-stage__label {
 143→  font-family: var(--sd-font-mono);
 144→  color: var(--sd-accent);
 145→  font-weight: 600;
 146→  font-size: 10px;
 147→  letter-spacing: 0.06em;
 148→  text-transform: uppercase;
 149→}
 150→
 151→.sd-stage__detail {
 152→  font-family: var(--sd-font-sans);
 153→  color: var(--sd-text-muted);
 154→  font-size: 11px;
 155→}
 156→
 157→@keyframes sd-pulse {
 158→  0%, 100% { opacity: 1; }
 159→  50% { opacity: 0.6; }
 160→}
 161→
 162→/* ── Messages Area ──────────────────────────────────────────────── */
 163→
 164→.sd-messages {
 165→  flex: 1;
 166→  overflow-y: auto;
 167→  padding: var(--space-md) var(--space-md) var(--space-md) var(--space-md);
 168→  padding-right: var(--space-sm);
 169→  display: flex;
 170→  flex-direction: column;
 171→  gap: var(--space-md);
 172→  background: var(--sd-canvas);
 173→}
 174→
 175→/* ── Message Bubbles ────────────────────────────────────────────── */
 176→
 177→.sd-message {
 178→  display: flex;
 179→  flex-direction: column;
 180→  gap: var(--sd-space-sm);
 181→  padding: var(--space-md) var(--space-lg);
 182→  margin-bottom: var(--space-md);
 183→  border-radius: 8px;
 184→  font-family: var(--sd-font-sans);
 185→  font-size: 13px;
 186→  line-height: 1.65;
 187→  word-wrap: break-word;
 188→}
 189→
 190→.sd-message--user {
 191→  background: var(--sd-card);
 192→  align-self: flex-end;
 193→  max-width: 90%;
 194→  border: 1px solid var(--sd-border-subtle);
 195→}
 196→
 197→.sd-message--agent {
 198→  background: var(--sd-panel);
 199→  align-self: flex-start;
 200→  max-width: 95%;
 201→  border-left: 2px solid var(--sd-accent-dim);
 202→}
 203→
 204→.sd-message--system {
 205→  background: transparent;
 206→  color: var(--sd-text-muted);
 207→  font-style: italic;
 208→  font-size: 11px;
 209→  align-self: center;
 210→}
 211→
 212→.sd-message__label {
 213→  font-family: var(--sd-font-mono);
 214→  font-size: 10.5px;
 215→  font-weight: 400;
 216→  color: var(--sd-text-muted);
 217→  text-transform: uppercase;
 218→  letter-spacing: 0.06em;
 219→  margin-bottom: 2px;
 220→}
 221→
 222→.sd-message--user .sd-message__label {
 223→  color: var(--sd-text-accent);
 224→}
 225→
 226→.sd-message--agent .sd-message__label {
 227→  color: var(--sd-accent);
 228→}
 229→
 230→.sd-message__body {
 231→  color: var(--sd-text-secondary);
 232→  max-width: 640px;
 233→  letter-spacing: 0.01em;
 234→}
 235→
 236→.sd-message--user .sd-message__body {
 237→  color: var(--sd-text-primary);
 238→}
 239→
 240→.sd-message--system .sd-message__body {
 241→  color: var(--sd-text-muted);
 242→}
 243→
 244→/* Visual breathing line between consecutive agent messages */
 245→.sd-message--agent + .sd-message--agent {
 246→  padding-top: var(--sd-space-xl);
 247→  border-top: 1px solid var(--sd-border-subtle);
 248→  margin-top: var(--sd-space-xs);
 249→}
 250→
 251→/* ── Text Rendering Classes ─────────────────────────────────────── */
 252→
 253→.sd-text-body {
 254→  font-family: var(--sd-font-sans);
 255→  font-size: 13px;
 256→  color: var(--sd-text-secondary);
 257→  line-height: 1.65;
 258→  letter-spacing: 0.01em;
 259→}
 260→
 261→.sd-text-body p {
 262→  margin: 0 0 var(--space-sm) 0;
 263→}
 264→
 265→.sd-text-body p:last-child {
 266→  margin-bottom: 0;
 267→}
 268→
 269→.sd-code-inline {
 270→  font-family: var(--sd-font-mono);
 271→  font-size: 11px;
 272→  background: var(--sd-elevated);
 273→  color: var(--sd-text-accent);
 274→  padding: var(--space-xs) var(--space-sm);
 275→  border-radius: 3px;
 276→  letter-spacing: 0.01em;
 277→}
 278→
 279→.sd-code-block {
 280→  font-family: var(--sd-font-mono);
 281→  font-size: 11.5px;
 282→  line-height: 1.65;
 283→  background: var(--sd-input);
 284→  color: var(--sd-text-primary);
 285→  padding: var(--space-md);
 286→  border-radius: 4px;
 287→  border: 1px solid var(--sd-border-subtle);
 288→  margin: var(--space-md) 0;
 289→  overflow-x: auto;
 290→  white-space: pre;
 291→}
 292→
 293→.sd-text-bold {
 294→  font-weight: 600;
 295→  color: var(--sd-text-primary);
 296→}
 297→
 298→/* ── Typing Indicator ───────────────────────────────────────────── */
 299→
 300→.sd-typing {
 301→  display: inline-flex;
 302→  align-items: center;
 303→  gap: var(--space-xs);
 304→  padding: var(--space-xs) 0;
 305→}
 306→
 307→.sd-typing__dot {
 308→  width: 5px;
 309→  height: 5px;
 310→  border-radius: 50%;
 311→  background: var(--sd-accent);
 312→  animation: sd-typing-pulse 1.2s ease-in-out infinite;
 313→}
 314→
 315→.sd-typing__dot:nth-child(2) {
 316→  animation-delay: 0.15s;
 317→}
 318→
 319→.sd-typing__dot:nth-child(3) {
 320→  animation-delay: 0.3s;
 321→}
 322→
 323→@keyframes sd-typing-pulse {
 324→  0%, 60%, 100% { opacity: 0.3; transform: scale(0.8); }
 325→  30% { opacity: 1; transform: scale(1); }
 326→}
 327→
 328→/* ── Input Bar ──────────────────────────────────────────────────── */
 329→
 330→.sd-input-bar {
 331→  display: flex;
 332→  gap: var(--space-xs);
 333→  padding: var(--space-sm) var(--space-md);
 334→  margin-top: var(--space-md);
 335→  border-top: 1px solid var(--sd-border);
 336→  background: var(--sd-panel);
 337→  flex-shrink: 0;
 338→}
 339→
 340→.sd-input {
 341→  flex: 1;
 342→  background: var(--sd-input);
 343→  border: 1px solid var(--sd-border);
 344→  border-radius: 6px;
 345→  padding: var(--space-sm) var(--space-md);
 346→  color: var(--sd-text-primary);
 347→  font-family: var(--sd-font-sans);
 348→  font-size: 12px;
 349→  outline: none;
 350→  transition: border-color var(--sd-transition);
 351→}
 352→
 353→.sd-input:focus {
 354→  border-color: var(--sd-accent);
 355→}
 356→
 357→.sd-input::placeholder {
 358→  color: var(--sd-text-muted);
 359→}
 360→
 361→.sd-send-btn {
 362→  background: var(--sd-accent);
 363→  color: #1a1a1a;
 364→  border: none;
 365→  border-radius: 6px;
 366→  padding: var(--space-sm) var(--space-md);
 367→  font-family: var(--sd-font-sans);
 368→  font-size: 12px;
 369→  font-weight: 600;
 370→  cursor: pointer;
 371→  transition: background var(--sd-transition), opacity var(--sd-transition);
 372→  flex-shrink: 0;
 373→}
 374→
 375→.sd-send-btn:hover {
 376→  opacity: 0.9;
 377→}
 378→
 379→.sd-send-btn:active {
 380→  opacity: 0.8;
 381→}
 382→
 383→.sd-send-btn:disabled {
 384→  background: var(--sd-elevated);
 385→  color: var(--sd-text-muted);
 386→  cursor: not-allowed;
 387→  opacity: 1;
 388→}
 389→
 390→/* ── Scrollbar ──────────────────────────────────────────────────── */
 391→
 392→.sd-messages::-webkit-scrollbar {
 393→  width: 3px;
 394→}
 395→
 396→.sd-messages::-webkit-scrollbar-track {
 397→  background: transparent;
 398→}
 399→
 400→.sd-messages::-webkit-scrollbar-thumb {
 401→  background: var(--sd-border);
 402→  border-radius: 2px;
 403→}
 404→
 405→.sd-messages::-webkit-scrollbar-thumb:hover {
 406→  background: var(--sd-text-muted);
 407→}
 408→
 409→/* ── Panel Components ───────────────────────────────────────────── */
 410→
 411→/* Panel container */
 412→.sd-panel {
 413→  background: var(--sd-panel);
 414→  border-radius: 6px;
 415→  border: 1px solid var(--sd-border-subtle);
 416→  overflow: hidden;
 417→  margin: var(--space-sm) 0;
 418→  max-width: 100%;
 419→}
 420→
 421→/* Panel header */
 422→.sd-panel__header {
 423→  padding: var(--space-md);
 424→}
 425→
 426→.sd-panel__label-row {
 427→  display: flex;
 428→  align-items: center;
 429→  justify-content: space-between;
 430→  margin-bottom: var(--space-sm);
 431→}
 432→
 433→.sd-panel__label {
 434→  font-family: var(--sd-font-mono);
 435→  font-size: 10px;
 436→  font-weight: 400;
 437→  color: var(--sd-text-muted);
 438→  text-transform: uppercase;
 439→  letter-spacing: 0.06em;
 440→}
 441→
 442→.sd-panel__badge {
 443→  font-family: var(--sd-font-mono);
 444→  font-size: 10px;
 445→  font-weight: 400;
 446→  color: var(--sd-accent);
 447→  background: var(--sd-accent-subtle);
 448→  padding: var(--space-xs) var(--space-sm);
 449→  border-radius: 3px;
 450→  letter-spacing: 0.01em;
 451→}
 452→
 453→.sd-panel__title {
 454→  font-family: var(--sd-font-sans);
 455→  font-size: 16px;
 456→  font-weight: 600;
 457→  color: var(--sd-text-primary);
 458→  letter-spacing: -0.02em;
 459→  margin-bottom: var(--space-xs);
 460→  line-height: 1.3;
 461→}
 462→
 463→.sd-panel__summary {
 464→  font-family: var(--sd-font-sans);
 465→  font-size: 12px;
 466→  font-weight: 500;
 467→  color: var(--sd-text-accent);
 468→  line-height: 1.65;
 469→  margin-bottom: var(--space-md);
 470→}
 471→
 472→.sd-panel__stats {
 473→  display: flex;
 474→  gap: var(--sd-space-xl);
 475→}
 476→
 477→.sd-panel__stat {
 478→  display: flex;
 479→  flex-direction: column;
 480→  gap: 1px;
 481→}
 482→
 483→.sd-panel__stat-value {
 484→  font-family: var(--sd-font-mono);
 485→  font-size: 14px;
 486→  font-weight: 600;
 487→  color: var(--sd-text-primary);
 488→}
 489→
 490→.sd-panel__stat-label {
 491→  font-family: var(--sd-font-sans);
 492→  font-size: 10px;
 493→  color: var(--sd-text-muted);
 494→}
 495→
 496→/* Collapsible section */
 497→.sd-section {
 498→  border-top: 1px solid var(--sd-border-subtle);
 499→}
 500→
 501→.sd-section__trigger {
 502→  display: flex;
 503→  align-items: center;
 504→  width: 100%;
 505→  padding: var(--space-sm) var(--space-md);
 506→  background: none;
 507→  border: none;
 508→  cursor: pointer;
 509→  color: var(--sd-text-primary);
 510→  font-family: var(--sd-font-sans);
 511→  font-size: 12px;
 512→  font-weight: 500;
 513→  letter-spacing: 0.01em;
 514→  text-align: left;
 515→  gap: var(--space-sm);
 516→  transition: background var(--sd-transition);
 517→}
 518→
 519→.sd-section__trigger:hover {
 520→  background: var(--sd-card);
 521→}
 522→
 523→.sd-section__dot {
 524→  width: 5px;
 525→  height: 5px;
 526→  border-radius: 50%;
 527→  flex-shrink: 0;
 528→}
 529→
 530→.sd-section__title {
 531→  flex: 1;
 532→}
 533→
 534→.sd-section__count {
 535→  font-family: var(--sd-font-mono);
 536→  font-size: 10px;
 537→  color: var(--sd-text-muted);
 538→  letter-spacing: 0.01em;
 539→}
 540→
 541→.sd-section__chevron {
 542→  font-size: 10px;
 543→  color: var(--sd-text-muted);
 544→  transition: transform var(--sd-transition);
 545→  flex-shrink: 0;
 546→}
 547→
 548→.sd-section--open > .sd-section__trigger .sd-section__chevron {
 549→  transform: rotate(90deg);
 550→}
 551→
 552→.sd-section__body {
 553→  padding: var(--space-sm) var(--space-md) var(--space-md);
 554→  display: none;
 555→}
 556→
 557→.sd-section--open > .sd-section__body {
 558→  display: block;
 559→}
 560→
 561→/* Slot tag */
 562→.sd-slot-tag {
 563→  display: inline-flex;
 564→  align-items: center;
 565→  gap: var(--space-xs);
 566→  padding: var(--space-xs) var(--space-sm);
 567→  border-radius: 3px;
 568→  font-family: var(--sd-font-mono);
 569→  font-size: 11px;
 570→  letter-spacing: 0.01em;
 571→  margin: 0 var(--space-xs) var(--space-xs) 0;
 572→}
 573→
 574→.sd-slot-tag__dot {
 575→  width: 5px;
 576→  height: 5px;
 577→  border-radius: 50%;
 578→  flex-shrink: 0;
 579→}
 580→
 581→/* Flow chain */
 582→.sd-flow-chain {
 583→  display: flex;
 584→  flex-wrap: wrap;
 585→  align-items: center;
 586→  gap: var(--space-xs);
 587→  padding: var(--space-xs) 0;
 588→}
 589→
 590→.sd-flow-chain__label {
 591→  font-family: var(--sd-font-mono);
 592→  font-size: 10px;
 593→  color: var(--sd-text-muted);
 594→  text-transform: uppercase;
 595→  letter-spacing: 0.06em;
 596→  margin-right: var(--sd-space-md);
 597→  width: 100%;
 598→  margin-bottom: var(--sd-space-xs);
 599→}
 600→
 601→.sd-flow-chain__node {
 602→  font-family: var(--sd-font-mono);
 603→  font-size: 11px;
 604→  padding: var(--space-xs) var(--space-sm);
 605→  border-radius: 3px;
 606→  letter-spacing: 0.01em;
 607→  white-space: nowrap;
 608→}
 609→
 610→.sd-flow-chain__arrow {
 611→  color: var(--sd-text-muted);
 612→  font-size: 10px;
 613→  padding: 0 2px;
 614→  user-select: none;
 615→}
 616→
 617→/* Detail row */
 618→.sd-detail-row {
 619→  display: flex;
 620→  align-items: baseline;
 621→  gap: var(--space-sm);
 622→  padding: var(--space-xs) 0;
 623→  line-height: 1.65;
 624→}
 625→
 626→.sd-detail-row + .sd-detail-row {
 627→  border-top: 1px solid #ffffff06;
 628→}
 629→
 630→.sd-detail-row__label {
 631→  font-family: var(--sd-font-sans);
 632→  font-size: 11px;
 633→  color: var(--sd-text-muted);
 634→  white-space: nowrap;
 635→}
 636→
 637→.sd-detail-row__leader {
 638→  flex: 1;
 639→  border-bottom: 1px dotted var(--sd-border);
 640→  min-width: 16px;
 641→  margin-bottom: 3px;
 642→}
 643→
 644→.sd-detail-row__value {
 645→  font-family: var(--sd-font-mono);
 646→  font-size: 10.5px;
 647→  color: var(--sd-text-secondary);
 648→  letter-spacing: 0.01em;
 649→  white-space: nowrap;
 650→  text-align: right;
 651→}
 652→
 653→/* Capability row */
 654→.sd-capability-row {
 655→  display: flex;
 656→  align-items: baseline;
 657→  gap: var(--space-sm);
 658→  padding: var(--space-xs) 0;
 659→  line-height: 1.65;
 660→}
 661→
 662→.sd-capability-row + .sd-capability-row {
 663→  border-top: 1px solid #ffffff06;
 664→}
 665→
 666→.sd-capability-row__dot {
 667→  width: 4px;
 668→  height: 4px;
 669→  border-radius: 50%;
 670→  flex-shrink: 0;
 671→  margin-top: 5px;
 672→}
 673→
 674→.sd-capability-row__label {
 675→  font-family: var(--sd-font-sans);
 676→  font-size: 11px;
 677→  font-weight: 500;
 678→  color: var(--sd-text-accent);
 679→  white-space: nowrap;
 680→}
 681→
 682→.sd-capability-row__sep {
 683→  flex: 1;
