 30→// ── Text Rendering ─────────────────────────────────────────────────
 31→
 32→/**
 33→ * Parse raw text into a DocumentFragment with styled elements.
 34→ * Handles: ```code blocks```, `inline code`, **bold**, paragraph breaks.
 35→ * NO innerHTML — all content via textContent.
 36→ */
 37→export function renderText(rawText) {
 38→  const frag = document.createDocumentFragment();
 39→  if (!rawText) return frag;
 40→
 41→  // Split on triple-backtick code blocks
 42→  const parts = rawText.split(/(```[\s\S]*?```)/);
 43→
 44→  for (const part of parts) {
 45→    if (part.startsWith("```") && part.endsWith("```")) {
 46→      // Code block — strip fences and optional language tag
 47→      let code = part.slice(3, -3);
 48→      // Remove optional language identifier on first line
 49→      const nlIdx = code.indexOf("\n");
 50→      if (nlIdx !== -1 && nlIdx < 20 && /^[a-zA-Z]*$/.test(code.slice(0, nlIdx).trim())) {
 51→        code = code.slice(nlIdx + 1);
 52→      }
 53→      // Trim leading/trailing newline
 54→      if (code.startsWith("\n")) code = code.slice(1);
 55→      if (code.endsWith("\n")) code = code.slice(0, -1);
 56→
 57→      const pre = document.createElement("pre");
 58→      pre.className = "sd-code-block";
 59→      pre.textContent = code;
 60→      frag.appendChild(pre);
 61→    } else {
 62→      // Text content — split into paragraphs on double newlines
 63→      const paragraphs = part.split(/\n{2,}/);
 64→      for (const para of paragraphs) {
 65→        const trimmed = para.trim();
 66→        if (!trimmed) continue;
 67→
 68→        const p = document.createElement("p");
 69→        _appendInlineMarkup(p, trimmed);
 70→        if (trimmed.length > 200) {
 71→          p.classList.add("sd-para-long");
 72→        }
 73→        frag.appendChild(p);
 74→      }
 75→    }
 76→  }
 77→
 78→  return frag;
 79→}
 80→
 81→/**
 82→ * Parse inline markup (**bold** and `code`) and append nodes to parent.
 83→ */
 84→function _appendInlineMarkup(parent, text) {
 85→  // Tokenize on **bold** and `code` patterns
 86→  const tokens = text.split(/(\*\*[^*]+\*\*|`[^`]+`)/);
 87→
 88→  for (const token of tokens) {
 89→    if (token.startsWith("**") && token.endsWith("**")) {
 90→      // Bold
 91→      const strong = document.createElement("strong");
 92→      strong.className = "sd-text-bold";
 93→      strong.textContent = token.slice(2, -2);
 94→      parent.appendChild(strong);
 95→    } else if (token.startsWith("`") && token.endsWith("`")) {
 96→      // Inline code
 97→      const code = document.createElement("code");
 98→      code.className = "sd-code-inline";
 99→      code.textContent = token.slice(1, -1);
100→      parent.appendChild(code);

