128→      el.classList.add(`sd-progress-stage--${status}`);
129→    }
130→  }
131→
132→  // ── Level 2: Progress bar
133→  if (data.progress !== undefined) {
134→    const track = panel.querySelector(".sd-progress-bar");
135→    const fill = panel.querySelector(".sd-progress-bar__fill");
