 55→/* ── WebSocket connection ─────────────────────────────────────────── */
 56→
 57→class AgentConnection {
 58→  constructor(onMessage, onStatus) {
 59→    this.ws = null;
 60→    this.onMessage = onMessage;   // (event) => void
 61→    this.onStatus = onStatus;     // (status) => void
 62→    this.reconnectDelay = 1000;
 63→    this.maxReconnectDelay = 15000;
 64→    this.currentDelay = this.reconnectDelay;
 65→    this._closed = false;
 66→  }
 67→
 68→  connect() {
 69→    const proto = location.protocol === "https:" ? "wss:" : "ws:";
 70→    const url = `${proto}//${location.host}/superduper/ws`;
 71→
 72→    this.onStatus("connecting");
 73→    this.ws = new WebSocket(url);
 74→
 75→    this.ws.onopen = () => {
 76→      this.currentDelay = this.reconnectDelay;
 77→      this.onStatus("connected");
 78→    };
 79→
 80→    this.ws.onmessage = (evt) => {
 81→      try {
 82→        const data = JSON.parse(evt.data);
 83→        this.onMessage(data);
 84→      } catch (e) {
 85→        console.error("[SUPER DUPER] Bad message:", evt.data);
 86→      }
 87→    };
 88→
 89→    this.ws.onclose = () => {
 90→      this.onStatus("disconnected");
 91→      if (!this._closed) {
 92→        setTimeout(() => this.connect(), this.currentDelay);
 93→        this.currentDelay = Math.min(this.currentDelay * 1.5, this.maxReconnectDelay);
 94→      }
 95→    };
 96→
 97→    this.ws.onerror = (err) => {
 98→      console.error("[SUPER DUPER] WebSocket error:", err);
 99→    };
100→  }
101→
102→  send(type, payload) {
103→    if (this.ws && this.ws.readyState === WebSocket.OPEN) {
104→      this.ws.send(JSON.stringify({ type, ...payload }));
105→      return true;
106→    }
107→    return false;
108→  }
109→
110→  close() {
111→    this._closed = true;
112→    if (this.ws) this.ws.close();
113→  }
114→}
