  1→/* ── SUPER DUPER Node FX ────────────────────────────────────────────
  2→ *  Canvas-level visual effects on ComfyUI nodes:
  3→ *    - Jade glow while executing
  4→ *    - Green flash on completion
  5→ *    - Agent-colored accent bar when touched by the AI
  6→ *  No innerHTML — all rendering via Canvas 2D context.
  7→ * ──────────────────────────────────────────────────────────────────── */
  8→
  9→import { app } from "../../../scripts/app.js";
 10→import { api } from "../../../scripts/api.js";
 11→
 12→// ── State ───────────────────────────────────────────────────────────
 13→
 14→let _executingNodeId = null;               // currently executing node
 15→const _completedNodes = new Map();         // nodeId -> completion timestamp
 16→
 17→const COMPLETE_FLASH_MS = 1000;
 18→const TOUCH_FADE_MS = 30000;
 19→
 20→const COLOR_JADE = "#00BB81";
 21→const COLOR_JADE_FILL = "#00BB8130";
 22→
 23→// ── Drawing ─────────────────────────────────────────────────────────
 24→
 25→function drawNodeFX(node, ctx) {
 26→  const nodeId = String(node.id);
 27→
 28→  // ── Executing: pulsing jade glow
 29→  if (nodeId === _executingNodeId) {
 30→    const pulse = 0.5 + Math.sin(Date.now() / 400) * 0.3;
 31→
 32→    ctx.save();
 33→    ctx.strokeStyle = COLOR_JADE;
 34→    ctx.lineWidth = 2;
 35→    ctx.shadowColor = COLOR_JADE;
 36→    ctx.shadowBlur = 15;
 37→    ctx.globalAlpha = pulse;
 38→
 39→    const r = 6;
 40→    const x = -r;
 41→    const y = -LiteGraph.NODE_TITLE_HEIGHT - r;
 42→    const w = node.size[0] + r * 2;
 43→    const h = node.size[1] + LiteGraph.NODE_TITLE_HEIGHT + r * 2;
 44→
 45→    ctx.beginPath();
 46→    ctx.roundRect(x, y, w, h, r);
 47→    ctx.stroke();
 48→    ctx.restore();
 49→
 50→    // Request continuous redraws for animation
 51→    if (node.graph) node.graph.change();
 52→  }
 53→
 54→  // ── Completed: brief green flash
 55→  const completedAt = _completedNodes.get(nodeId);
 56→  if (completedAt) {
 57→    const elapsed = Date.now() - completedAt;
 58→    if (elapsed < COMPLETE_FLASH_MS) {
 59→      const alpha = 1 - elapsed / COMPLETE_FLASH_MS;
 60→
 61→      ctx.save();
 62→      ctx.fillStyle = COLOR_JADE_FILL;
 63→      ctx.globalAlpha = alpha;
 64→
 65→      const y = -LiteGraph.NODE_TITLE_HEIGHT;
 66→      ctx.beginPath();
 67→      ctx.roundRect(0, y, node.size[0], node.size[1] + LiteGraph.NODE_TITLE_HEIGHT, 4);
 68→      ctx.fill();
 69→      ctx.restore();
 70→
 71→      if (node.graph) node.graph.change();
 72→    } else {
 73→      _completedNodes.delete(nodeId);
 74→    }
 75→  }
 76→
 77→  // ── Agent-touched: colored left-edge bar
 78→  if (node._sd_touch) {
 79→    const elapsed = Date.now() - node._sd_touch.time;
 80→    if (elapsed < TOUCH_FADE_MS) {
 81→      const alpha = 1 - elapsed / TOUCH_FADE_MS;
 82→
 83→      ctx.save();
 84→      ctx.fillStyle = node._sd_touch.color || COLOR_JADE;
 85→      ctx.globalAlpha = alpha;
 86→
 87→      const barH = node.size[1] + LiteGraph.NODE_TITLE_HEIGHT;
 88→      ctx.fillRect(-1, -LiteGraph.NODE_TITLE_HEIGHT, 3, barH);
 89→      ctx.restore();
 90→
 91→      if (node.graph) node.graph.change();
 92→    } else {
 93→      delete node._sd_touch;
 94→    }
 95→  }
 96→}
